'use strict';
const results={'primary-example':'Sample task marked complete.','secondary-example':'Preview opened in this component example.','quiet-example':'Current example plan kept.','accent-example':'Course exploration action selected.','icon-example':'A sample task was added.'};
Object.entries(results).forEach(([id,message])=>document.getElementById(id).onclick=()=>{document.getElementById('action-result').textContent=message});
document.getElementById('component-theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';persist();applyTheme();document.getElementById('component-theme').setAttribute('aria-label',`Change theme. Current theme: ${state.theme}`)};
const tabs=[...document.querySelectorAll('[role=tab]')],copy=[['Keep the work in order.','Ordered modules and tasks make the next step clear. Resources remain separate from required work.'],['Your completion is a separate record.','Completing a task does not invent time spent. A timer does not automatically complete a task.'],['Compare the same scope.','Course progress uses a reviewed, fixed required-task denominator. Hours use eligible recorded duration.']];
function chooseTab(index,focus=false){tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',i===index);tab.tabIndex=i===index?0:-1});const panel=document.getElementById('sample-panel');panel.setAttribute('aria-labelledby',tabs[index].id);panel.innerHTML=`<h3>${copy[index][0]}</h3><p style="margin-top:8px">${copy[index][1]}</p>`;if(focus)tabs[index].focus()}
tabs.forEach((tab,i)=>{tab.onclick=()=>chooseTab(i);tab.onkeydown=e=>{let next=i;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();chooseTab(next,true)}});
document.getElementById('component-form').onsubmit=e=>{e.preventDefault();const title=document.getElementById('sample-title'),error=document.getElementById('title-error');if(!title.value.trim()){title.setAttribute('aria-invalid','true');error.className='error-message';error.textContent='Enter a course title before saving this example.';title.focus()}else{title.removeAttribute('aria-invalid');error.className='';error.textContent='';document.getElementById('form-result').textContent='Example saved for this page session only.'}};
document.getElementById('component-form').onreset=()=>{document.getElementById('sample-title').removeAttribute('aria-invalid');document.getElementById('title-error').textContent='';document.getElementById('title-error').className='';document.getElementById('form-result').textContent=''};
document.getElementById('loading-example').onclick=e=>{document.getElementById('sample-loading').outerHTML='<span class="badge success" role="status">Preview ready</span>';e.target.disabled=true};
document.getElementById('retry-example').onclick=e=>{e.target.parentElement.innerHTML='<strong role="status">The example is ready.</strong><p style="margin-top:8px">Your draft has been preserved. This is a simulated recovery state.</p>'};
document.getElementById('sample-switch').onclick=e=>{const el=e.currentTarget,on=el.getAttribute('aria-checked')!=='true';el.setAttribute('aria-checked',on);document.getElementById('switch-status').textContent=`Example preference: ${on?'on':'off'}.`};
